#!/usr/bin/env node

// src/errors.ts
import { log } from "@clack/prompts";
var ExitCode = {
  Ok: 0,
  Error: 1,
  InternalError: 2
};
function getErrorMessage(err) {
  return err instanceof Error ? err.message : String(err);
}
var verbose = false;
function setVerbose(value) {
  verbose = value;
}
function isVerbose() {
  return verbose;
}
function reportError(err) {
  log.error(getErrorMessage(err));
  if (verbose && err instanceof Error && err.stack) {
    console.error(err.stack);
  }
}
var GramCLIError = class extends Error {
  constructor(message, exitCode = ExitCode.InternalError) {
    super(message);
    this.exitCode = exitCode;
    this.name = "GramCLIError";
  }
  exitCode;
};
var GramConfigError = class extends GramCLIError {
  constructor(message) {
    super(message, ExitCode.Error);
    this.name = "GramConfigError";
  }
};

export {
  ExitCode,
  getErrorMessage,
  setVerbose,
  isVerbose,
  reportError,
  GramCLIError,
  GramConfigError
};
